        foreach (Material m in lightMaterialDatabaseSo.GetAllLightGunLightsExceptOff()) {
            m.DOFloat(Constants.LightGunLightEmissionAmount, "_MyEmissiveIntensity", 2f);
        }

        emergencyLights.SetActive(true);
    }

    private void LightsBackOn() {
        LevelEventHub.LightsBackOn();
        GlobalInGameData.IsPowerOn = true;

        foreach (Material m in lightMaterialDatabaseSo.GetAllLightGunLightsExceptOff()) {
            m.DOFloat(0f, "_MyEmissiveIntensity", 2f);
        }

        emergencyLights.SetActive(false);
    }
}
