    [Header("Insert animation duration")]
    [SerializeField] private float insertAnimationDuration1 = 0.5f, insertAnimationDuration2 = 0.5f;

    public void OnEnteredPowerStation(Action OnInserted) {
        if (IsGrabbed) UnGrab(false);

